/**
 * NONACTIVATED WORM archive transport. Actual S3 Object Lock COMPLIANCE
 * API commands, no in-memory substitute, credentials, or production wiring.
 * The independent security operator MUST control versioning, Object Lock,
 * credentials, lifecycle, retention and account deletion outside this module.
 * Receipts are generated by the restricted independent witness SQL attestor.
 */
import crypto from 'node:crypto';
import {Buffer} from 'node:buffer';

const SUBJECT=/^[a-f0-9]{64}$/u;
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/u;
const CID=/^bafyre[a-z2-7]{53}$/u;
const REV=/^[1-9][0-9]{0,18}$/u;
const MAX=9223372036854775807n;
const DAY=86400000;
const BUCKET=/^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$/u;
const MAX_BYTES=1024;
const EPOCH_KEY=/^paper\/oauth-witness\/epochs\/v1\/([a-f0-9]{64})\/([0-9]{19})$/u;
const INTENT_KEY=/^paper\/oauth-witness\/signed-intents\/v1\/([0-9a-f-]{36})\/(pending|resolved)$/u;
function deny(code) {
 const e=new Error('Immutable S3 compliance receipt unavailable');
 e.code=code;
 throw e;
}
function asRevision(value){
 if(!REV.test(value)||BigInt(value)>MAX)deny('S3_RECEIPT_FORMAT_INVALID');
 return value;
}
function assertReceipt(key,bytes){
 if(typeof key!=='string'||!Buffer.isBuffer(bytes)||bytes.length<32||
    bytes.length>MAX_BYTES)deny('S3_RECEIPT_FORMAT_INVALID');
 const s=bytes.toString('utf8');
 if(!Buffer.from(s,'utf8').equals(bytes)||
    /[^\x20-\x7e\n]/u.test(s))deny('S3_RECEIPT_FORMAT_INVALID');
 const epoch=EPOCH_KEY.exec(key);
 if(epoch){
  let v;
  try{v=JSON.parse(s)}catch{deny('S3_RECEIPT_FORMAT_INVALID')}
  if(!v||Object.keys(v).sort().join(',')!==
      'eventSha256,kind,operationId,revision,subject'||
     v.kind!=='paper.witness.epoch.v1'||v.subject!==epoch[1]||
     !SUBJECT.test(v.eventSha256)||!UUID.test(v.operationId)||
     asRevision(String(v.revision))!==v.revision||
     v.revision.padStart(19,'0')!==epoch[2]||
     JSON.stringify(v)!==s)deny('S3_RECEIPT_FORMAT_INVALID');
  return;
 }
 const intent=INTENT_KEY.exec(key);
 if(!intent||!UUID.test(intent[1]))deny('S3_RECEIPT_FORMAT_INVALID');
 const f=s.split('\n');
 if(f.length!==12||f[11]!==''||
    f[0]!=='paper:witness:signed-intent:v1'||
    !SUBJECT.test(f[1])||f[2]!==intent[1]||
    asRevision(f[3])!==f[3]||
    !SUBJECT.test(f[4])||!SUBJECT.test(f[5])||
    !CID.test(f[6])||!CID.test(f[7])||
    f[6]===f[7]||f[8]!==intent[2])deny('S3_RECEIPT_FORMAT_INVALID');
 if(intent[2]==='pending'){
  if(f[9]!=='pending'||f[10]!=='-')deny('S3_RECEIPT_FORMAT_INVALID');
 }else{
  if((f[9]!=='committed'&&f[9]!=='aborted')||
    (f[9]==='committed'&&f[10]!==f[7])||
    (f[9]==='aborted'&&f[10]!=='-'))
   deny('S3_RECEIPT_FORMAT_INVALID');
 }
}
function validDate(value){
 const n=value instanceof Date?value.getTime():typeof value==='string'?Date.parse(value):NaN;
 return Number.isFinite(n)?n:NaN;
}
async function getBounded(body){
 if(Buffer.isBuffer(body)||body instanceof Uint8Array){
  if(body.length>MAX_BYTES)deny('S3_RECEIPT_READBACK_TOO_LARGE');
  return Buffer.from(body);
 }
 if(!body||typeof body[Symbol.asyncIterator]!=='function')
  deny('S3_RECEIPT_READBACK_INVALID');
 const chunks=[];let total=0;
 try{
  for await(const part of body){
   if(!(part instanceof Uint8Array))deny('S3_RECEIPT_READBACK_INVALID');
   total+=part.byteLength;
   if(total>MAX_BYTES)deny('S3_RECEIPT_READBACK_TOO_LARGE');
   chunks.push(Buffer.from(part));
  }
 }catch(e){
  if(e?.code?.startsWith('S3_RECEIPT_'))throw e;
  deny('S3_RECEIPT_READBACK_UNAVAILABLE');
 }
 return Buffer.concat(chunks,total);
}
/**
 * Clients MUST have DIFFERENT real IAM principals / management accounts.
 * Constructor identity inequality is a minimal sanity test, not an IAM audit.
 * Writer: s3:PutObject (create-only, no delete/retention admin).
 * Reader: GetObjectVersion, HeadObject, GetObjectRetention,
 * GetBucketVersioning, GetBucketObjectLockConfiguration; no write.
 *
 * SDK commands are injected from pinned @aws-sdk/client-s3:
 * PutObjectCommand, HeadObjectCommand, GetObjectCommand,
 * GetObjectRetentionCommand, GetBucketVersioningCommand,
 * GetObjectLockConfigurationCommand.
 * Caller never obtains signed-write or witness SQL credentials.
 */
export function createS3ComplianceReceiptArchive({
 writer,reader,commands,bucket,minRetentionDays=400,
 clock=()=>Date.now(),fixtureOnly=false
}={}){
 // The archive is intentionally NOT connected to production services yet.
 // Test flag prevents a test transport or misconfigured store from silently
 // being promoted into a real release authority.
 if(fixtureOnly!==true||process.env.NODE_ENV!=='test'||
    process.env.PAPER_OAUTH_S3_COMPLIANCE_DISPOSABLE!=='confirmed')
  deny('S3_RECEIPT_NOT_RELEASED');
 if(!writer||!reader||writer===reader||
    typeof writer.send!=='function'||typeof reader.send!=='function'||
    typeof bucket!=='string'||!BUCKET.test(bucket)||
    !Number.isSafeInteger(minRetentionDays)||
    minRetentionDays<365||minRetentionDays>3650||
    typeof clock!=='function')deny('S3_RECEIPT_CONFIGURATION_INVALID');
 const names=['PutObjectCommand','HeadObjectCommand','GetObjectCommand',
  'GetObjectRetentionCommand','GetBucketVersioningCommand',
  'GetObjectLockConfigurationCommand'];
 if(names.some(n=>typeof commands?.[n]!=='function'))
  deny('S3_RECEIPT_CONFIGURATION_INVALID');
 const send=async(client,command)=>{
  try{
   return await client.send(command,{
    abortSignal:AbortSignal.timeout(7000)
   });
  }catch(e){throw e}
 };
 const command=(type,args)=>new commands[type](args);
 async function lockPolicy(){
  let versions,policy;
  try{
   [versions,policy]=await Promise.all([
    send(reader,command('GetBucketVersioningCommand',{Bucket:bucket})),
    send(reader,command('GetObjectLockConfigurationCommand',{Bucket:bucket}))
   ]);
  }catch{deny('S3_RECEIPT_LOCK_UNVERIFIED')}
  const lock=policy?.ObjectLockConfiguration;
  const base=lock?.Rule?.DefaultRetention;
  const days=Number(base?.Days??0)+365*Number(base?.Years??0);
  if(versions?.Status!=='Enabled'||lock?.ObjectLockEnabled!=='Enabled'||
     base?.Mode!=='COMPLIANCE'||!Number.isSafeInteger(days)||
     days<minRetentionDays)
   deny('S3_RECEIPT_LOCK_UNVERIFIED');
 }
 async function independentlyVerify({key,bytes,retentionFloor}){
  await lockPolicy();
  let head;
  try{head=await send(reader,command('HeadObjectCommand',{Bucket:bucket,Key:key}))}
  catch{deny('S3_RECEIPT_HEAD_UNAVAILABLE')}
  const version=head?.VersionId;
  if(typeof version!=='string'||!version||version==='null'||
     version.length>1024||head.DeleteMarker===true||
     head.ContentLength!==bytes.length)
   deny('S3_RECEIPT_HEAD_INVALID');
  let retention,read;
  try{
   [retention,read]=await Promise.all([
    send(reader,command('GetObjectRetentionCommand',{
      Bucket:bucket,Key:key,VersionId:version
    })),
    send(reader,command('GetObjectCommand',{
      Bucket:bucket,Key:key,VersionId:version
    }))
   ]);
  }catch{deny('S3_RECEIPT_READBACK_UNAVAILABLE')}
  if(retention?.Retention?.Mode!=='COMPLIANCE'||
     validDate(retention.Retention.RetainUntilDate)<retentionFloor)
    deny('S3_RECEIPT_RETENTION_UNVERIFIED');
  if(read?.VersionId!==version)
   deny('S3_RECEIPT_VERSION_MISMATCH');
  const actual=await getBounded(read.Body);
  if(actual.length!==bytes.length||
     !crypto.timingSafeEqual(actual,bytes))deny('S3_RECEIPT_BYTES_MISMATCH');
  let current;
  try{current=await send(reader,command('HeadObjectCommand',{
   Bucket:bucket,Key:key
  }))}catch{deny('S3_RECEIPT_CURRENT_UNAVAILABLE')}
  if(current?.VersionId!==version||current.DeleteMarker===true)
   deny('S3_RECEIPT_VERSION_CHANGED');
  await lockPolicy();
  return Object.freeze({key,versionId:version,
   sha256:crypto.createHash('sha256').update(actual).digest('hex')});
 }
 return Object.freeze({
  async putAndVerify({key,bytes}={}){
   assertReceipt(key,bytes);
   const now=clock();
   if(!Number.isSafeInteger(now)||now<=0)
    deny('S3_RECEIPT_CLOCK_UNSAFE');
   const floor=now+minRetentionDays*DAY;
   await lockPolicy();
   try{
    await send(writer,command('PutObjectCommand',{
     Bucket:bucket,Key:key,Body:Buffer.from(bytes),
     IfNoneMatch:'*',ContentType:'application/octet-stream',
     ContentMD5:crypto.createHash('md5').update(bytes).digest('base64'),
     ChecksumSHA256:crypto.createHash('sha256').update(bytes).digest('base64')
    }));
   }catch{
    // 412 and lost PUT ACK are ambiguous. A second create, truncate or
    // overwrite is forbidden; independent exact-version readback is mandatory.
   }
   return independentlyVerify({key,bytes,retentionFloor:floor});
  }
 });
}
